package com.limagiran.bible.util;

import java.awt.Color;
import java.awt.Font;
import java.awt.Window.Type;
import javax.swing.ImageIcon;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import javax.xml.bind.DatatypeConverter;

public class PopUpWorker extends JDialog {
   private static final ImageIcon DEFAULT_ICON = new ImageIcon(
      DatatypeConverter.parseBase64Binary(
         ""
      )
   );
   private static final String IMAGE_BASE_64 = "";
   private JLabel l;

   private PopUpWorker(MySwingWorker worker) {
      super(worker.owner);
      this.init(worker);
   }

   private void init(MySwingWorker worker) {
      this.setDefaultCloseOperation(0);
      worker.setupPopup(this);
      this.setTitle("Bible LG");
      this.setModal(true);
      this.setResizable(false);
      this.setType(Type.POPUP);
      this.setUndecorated(true);
      Border border = new CompoundBorder(new LineBorder(Color.LIGHT_GRAY, 1), new LineBorder(Color.GRAY, 1));
      this.getRootPane().setBorder(new CompoundBorder(border, new EmptyBorder(6, 12, 6, 12)));
      this.l = new JLabel("  " + worker.msg, DEFAULT_ICON, 0);
      this.l.setFont(new Font("Arial", 0, 28));
      this.getContentPane().add(this.l);
      this.pack();
      this.setLocationRelativeTo(null);
   }

   public void setMessage(String message) {
      SwingUtilities.invokeLater(() -> {
         try {
            this.l.setText("  " + message);
            this.pack();
            this.setLocationRelativeTo(null);
         } catch (Exception var3) {
         }
      });
   }

   public static void exe(MySwingWorker worker) {
      SwingUtilities.invokeLater(() -> new PopUpWorker(worker).setVisible(true));
   }
}
